//! The wire types: generated by `build.rs` from `docs/protocol.schema.json` and never written by
//! hand. Only `Call`, the one trait the generated calls implement, and how an `Ok` outcome is
//! shown (D30: its text, then one `[image WxH mime]` line per image), are here.

use serde::{Serialize, de::DeserializeOwned};

/// A call of the protocol: the params type names its method and the type of its result.
pub trait Call: Serialize {
    const METHOD: &'static str;
    type Output: DeserializeOwned;
}

#[allow(clippy::all, clippy::pedantic, dead_code, unused_imports)]
mod generated {
    use super::Call;
    include!(concat!(env!("OUT_DIR"), "/wire.rs"));
}

pub use generated::*;

impl OutcomeOk {
    /// The text the tool returned.
    pub fn value(&self) -> &str {
        match self {
            Self::String(value) | Self::Object { value, .. } => value,
        }
    }

    /// The text, then one line per image, `[image WxH mime]`; never the bytes (D30).
    pub fn shown(&self) -> String {
        let Self::Object { value, images } = self else {
            return self.value().to_owned();
        };
        let lines = images
            .iter()
            .map(|i| format!("[image {}x{} {}]", i.width, i.height, i.mime));
        let text = (!value.is_empty()).then(|| value.clone());
        text.into_iter().chain(lines).collect::<Vec<_>>().join("\n")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn both_shapes_of_ok_read_and_an_image_shows_as_one_line() {
        let plain: Outcome = serde_json::from_str(r#"{"Ok":"text"}"#).unwrap();
        let Outcome::Ok(ok) = plain else { panic!() };
        assert_eq!(ok.shown(), "text");
        let image = r#"{"mime":"image/png","sha256":"ab","width":3,"height":2}"#;
        let mixed = format!(r#"{{"Ok":{{"value":"seen","images":[{image}]}}}}"#);
        let Outcome::Ok(ok) = serde_json::from_str(&mixed).unwrap() else {
            panic!()
        };
        assert_eq!(ok.value(), "seen");
        assert_eq!(ok.shown(), "seen\n[image 3x2 image/png]");
        let alone = format!(r#"{{"Ok":{{"value":"","images":[{image}]}}}}"#);
        let Outcome::Ok(ok) = serde_json::from_str(&alone).unwrap() else {
            panic!()
        };
        assert_eq!(ok.shown(), "[image 3x2 image/png]");
    }
}
